func monitorSharedState(ctx context.Context, ticks <-chan time.Time, systemDatabase sharedStateDatabase, global sharedSettings, packages sharedPackageState, publicNetwork servicePlaneGate, logger *slog.Logger) {
	available := true
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticks:
			checkContext, cancel := context.WithTimeout(ctx, 5*time.Minute)
			err := reconcileSharedState(checkContext, systemDatabase, global, publicNetwork, packages)
			cancel()
			if err != nil && available {
				available = false
				if logger != nil {
					logger.Error("shared database unavailable; public service plane gated", "error", err)
				}
			} else if err == nil && !available {
				available = true
				if logger != nil {
					logger.Info("shared database recovered; public service plane restored")
				}
			}
		}
	}
}
